import{_ as o,l as s,o as e,c as i,v as t,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"用户线程对内核线程","description":"","frontmatter":{"title":"用户线程对内核线程","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ult-klt.md","filePath":"cs/ult-klt.md","lastUpdated":1789023840000}'),h={name:"cs/ult-klt.md"};function m(_,a,T,u,B,E){const l=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="用户线程对内核线程" tabindex="-1">用户线程对内核线程 <a class="header-anchor" href="#用户线程对内核线程" aria-label="Permalink to &quot;用户线程对内核线程&quot;">​</a></h1><div class="epigraph"><p>内核只能调度它看见的内核线程；用户级线程库在一条内核线程上自己切栈，阻塞一次系统调用会卡住整个库。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Tanenbaum MOS 整理</footer></div><p><a href="/cs/thread-shared-addr">上一课</a>钉死：同进程多条控制流共享页表，各有栈与寄存器。缺口是<strong>谁来切换这些流</strong>：若每条 POSIX 线程对应一个 PCB（1:1），内核全看见；若 N 条用户线程复用 1 条内核线程（N:1），内核只看见一个调度实体。本课对照这两种映射，不写具体绿线程库。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>1:1：创建线程就是再分配 PCB 与内核栈，阻塞 <code>read</code> 只挡这一条，其它内核线程仍跑。代价是每次用户切换都可能陷入。<a href="/cs/context-switch">上下文切换</a> 对内核可见。N:1：用户库改栈指针即「切换」，快，但该内核线程一睡，全部用户线程停。M:N 要内核与库协同，复杂。缺口不是共享堆的定义，而是调度可见性。</p><p><span class="marginnote">当代 Linux 上的 NPTL 是 1:1。用户态协程仍存在，但阻塞系统调用要么包装成非阻塞，要么接受卡住工人线程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>教学默认后续调度课调度的是内核线程（KLT）。提到 ULT 只为解释：库内切换不经过 trapframe 交换两个 PCB。混合模型里，内核提供若干工人 KLT，库把 ULT 绑上去；工人阻塞则库需再开工人——本课只点到，不设计调度器。</p>',8)),(e(),n(p,null,{default:r(()=>[c(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%E7%BA%BF%E7%A8%8B%22%5D%20--%3E%20M1%5B%221%3A1%20%E5%90%84%E6%9C%89%20PCB%22%5D%0A%20%20U%20--%3E%20MN%5B%22N%3A1%20%E5%85%B1%E7%94%A8%E4%B8%80%E4%B8%AA%20PCB%22%5D%0A%20%20M1%20--%3E%20SCH%5B%22%E5%86%85%E6%A0%B8%E8%B0%83%E5%BA%A6%22%5D%0A%20%20MN%20--%3E%20LIB%5B%22%E5%BA%93%E5%86%85%E5%88%87%E6%A0%88%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><a href="/cs/syscall-path">系统调用路径</a> 总是由当前这条 KLT 陷入。ULT 的「当前」若与陷入的 KLT 不一致，库必须在陷入前记下。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>映射决定阻塞语义与并行度。多核上 N:1 无法把同一进程的线程真正并行到两颗 CPU——只有一个 PCB。1:1 可以。实时优先级也只作用在 KLT 上；纯 ULT 的优先级是库自己的假象。这把后课的运行队列对象钉死：队列里是 PCB，不是用户库的协程控制块。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Go 调度器或 Java 虚拟线程的实现写成 OS 主干。也不把 GPU warp 当线程模型。fork 与多线程的 POSIX 规则上一课已点过。</p><p>后课默认：内核调度实体是 KLT。同进程线程仍要有一份内核看不见的<strong>每线程数据</strong>（errno、locale），下一课讲线程局部存储。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内核只调度 KLT；ULT 切栈快但阻塞会连坐。</li><li>1:1 才能真正多核并行同一进程的线程。</li><li>每线程私有数据槽是下一课 TLS。</li><li>出处：Silberschatz et al., <em>OSC</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',8))])}const P=o(h,[["render",m]]);export{A as __pageData,P as default};
